"""Study 1: which requirements end up in code generated by an LLM.

For every module in apps/ the script builds prompts from spec.yaml, sends them to the selected
models, extracts the returned code and runs one test per requirement on it.

Conditions
    FULL     description, API and all requirements of the module
    ABL-<r>  the same prompt without requirement r (one prompt per requirement)

Every request is saved as one JSON file in results/<name>/ (prompt, raw response, extracted code,
API parameters, tokens, cost and the test result of every requirement). Files are never
overwritten, so an interrupted run can simply be started again and only missing requests are sent.
After each run the JSON files are copied into results/<name>/results.csv.

Erosion (--erosion) takes the code of every FULL run and asks the same model to apply the four
change requests from spec.yaml one after another, running all tests after each step.
With --refactor there is a single step instead: "refactor this module", same API.

Usage
    python run.py --check                                            # validate tests with reference and mutants
    python run.py --name main --models chatgpt,qwen --reps 3 --budget 5
    python run.py --name main --models chatgpt,qwen --reps 3 --budget 5 --erosion
    python run.py --name main --models qwen --apps uploads,library --reps 3 --budget 1 --erosion --refactor
    python run.py --name main --report                               # rebuild the CSV files from the JSON files

API keys are read from environment variables (see MODELS). Code generated by the models is
executed during testing, so run this in a container or virtual machine.
"""
import argparse
import csv
import hashlib
import io
import json
import os
import random
import re
import shutil
import subprocess
import sys
import tempfile
import time
from datetime import datetime, timezone
from pathlib import Path

import yaml

# name: (API base URL, environment variable with the key, model ID, USD per 1M input tokens, USD per 1M output tokens)
# Prices are used only for the budget limit (--budget) and the cost_usd column.
MODELS = {
    "mock":     ("mock", None, "reference", 0, 0),  # returns reference.py, for testing without API keys
    "deepseek": ("https://api.deepseek.com", "DEEPSEEK_API_KEY", "deepseek-flash", 0.30, 1.20),
    "gemini":   ("https://generativelanguage.googleapis.com/v1beta/openai/", "GEMINI_API_KEY", "gemini-3.8-flash", 0.75, 3.75),
    "chatgpt":  ("https://api.openai.com/v1", "OPENAI_API_KEY", "gpt-6.1-terra", 1.00, 5.00),
    "claude":   ("https://openrouter.ai/api/v1", "OPENROUTER_API_KEY", "anthropic/claude-sonnet-5.5", 2.00, 10.00),
    "qwen":     ("https://openrouter.ai/api/v1", "OPENROUTER_API_KEY", "qwen/qwen-plus", 0.40, 1.20),
    "llama":    ("https://openrouter.ai/api/v1", "OPENROUTER_API_KEY", "meta-llama/llama-3.3-70b-instruct", 0.10, 0.32),
}

# name: (reasoning level, output token limit including hidden reasoning)
# reasoning level: None = send nothing (provider default), "off", "low", "medium" or "high"
SETTINGS = {
    "deepseek": ("off", 16000),
    "gemini":   ("low", 16000),
    "chatgpt":  ("low", 16000),
    "claude":   ("low", 16000),
    "qwen":     (None, 16000),
    "llama":    (None, 16000),
}
DEFAULT_MAX_TOKENS = 16000

# How each provider expects the reasoning level to be sent.
REASONING_STYLE = {"deepseek": "deepseek", "gemini": "effort", "chatgpt": "effort",
                   "claude": "openrouter", "qwen": "qwen"}

REFACTOR = ("Refactor this module to make it cleaner, simpler and more idiomatic Python. "
            "Keep the public API (class name, method names and signatures) unchanged.")

ROOT = Path(__file__).parent
APPS = ROOT / "apps"
SPENT = {"usd": 0.0, "budget": 1.0}
RUN = {}  # experiment name, run ID and output folder of the current run


class BudgetExceeded(Exception):
    pass


class CallFailed(Exception):
    pass


def settings(model):
    """Return (reasoning level, token limit, extra API parameters) for a model."""
    level, max_tokens = SETTINGS.get(model, (None, DEFAULT_MAX_TOKENS))
    if level is None or model == "mock":
        return level, max_tokens, {}
    if level not in ("off", "low", "medium", "high"):
        sys.exit(f"SETTINGS[{model!r}]: unknown reasoning level {level!r}")
    style = REASONING_STYLE.get(model)
    if style == "deepseek":
        params = ({"extra_body": {"thinking": {"type": "disabled"}}} if level == "off"
                  else {"reasoning_effort": level, "extra_body": {"thinking": {"type": "enabled"}}})
    elif style == "effort":
        params = {"reasoning_effort": "none" if level == "off" else level}
    elif style == "openrouter":
        params = {"extra_body": {"reasoning": {"effort": "minimal" if level == "off" else level}}}
    elif style == "qwen":
        params = {"extra_body": {"enable_thinking": level != "off"}}
    else:
        sys.exit(f"SETTINGS[{model!r}]: no reasoning style defined for this model, use None")
    return level, max_tokens, params


def now():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def app_hash(app_dir):
    """Short hash of spec.yaml and the tests, stored with every result."""
    h = hashlib.sha256()
    for f in [app_dir / "spec.yaml", *sorted((app_dir / "tests").glob("*.py"))]:
        h.update(f.read_bytes())
    return h.hexdigest()[:12]


def ask(model, prompt, app_dir):
    """Send one prompt. Return (text, input tokens, output tokens, stop reason, raw API response)."""
    url, key_env, model_id, _, _ = MODELS[model]
    if url == "mock":
        ref = app_dir / "reference.py"
        code = ref.read_text() if ref.exists() else "print('mock')\n"
        return f"```python\n{code}```", len(prompt) // 4, len(code) // 4, "stop", {"mock": True}
    from openai import OpenAI  # imported here so that --check, --report and the analysis work without it
    _, max_tokens, params = settings(model)
    limit = {"max_completion_tokens" if model == "chatgpt" else "max_tokens": max_tokens}
    r = OpenAI(api_key=os.environ[key_env], base_url=url).chat.completions.create(
        model=model_id, messages=[{"role": "user", "content": prompt}], **limit, **params)
    u = r.usage
    # Gemini bills reasoning tokens without counting them in completion_tokens,
    # so everything except the prompt is counted as output.
    out_tokens = max(u.completion_tokens or 0, (u.total_tokens or 0) - (u.prompt_tokens or 0))
    return (r.choices[0].message.content or "", u.prompt_tokens, out_tokens,
            r.choices[0].finish_reason, r.model_dump())


def call(model, prompt, app_dir):
    """Send a prompt within the budget, with retries. Return the response, extracted code, tokens and cost."""
    price_in, price_out = MODELS[model][3:]
    level, max_tokens, params = settings(model)
    worst_case = (len(prompt) / 3 * price_in + max_tokens * price_out) / 1e6
    if SPENT["usd"] + worst_case > SPENT["budget"]:
        raise BudgetExceeded
    start = time.time()
    for wait in [10, 30, 90, None]:
        try:
            text, tokens_in, tokens_out, stop, raw = ask(model, prompt, app_dir)
            break
        except Exception as e:
            status = getattr(e, "status_code", None)
            if status and 400 <= status < 500 and status != 429:  # bad request or key: retrying will not help
                raise CallFailed(f"{model}: error {status}: {str(e)[:300]}")
            if wait is None:
                raise CallFailed(f"{model}: {type(e).__name__}: {e}")
            print(f"   ! {model}: {type(e).__name__}: {str(e)[:120]}, retrying in {wait} s", flush=True)
            time.sleep(wait)
    cost = (tokens_in * price_in + tokens_out * price_out) / 1e6
    SPENT["usd"] += cost
    blocks = re.findall(r"```[ \t]*[A-Za-z0-9_+-]*[ \t]*\n(.*?)```", text, re.S)
    return {"model_id": MODELS[model][2], "prompt": prompt, "response": text,
            "code": max(blocks, key=len) if blocks else text,
            "input_tokens": tokens_in, "output_tokens": tokens_out, "cost_usd": cost,
            "stop_reason": stop, "truncated": stop in ("length", "max_tokens"),
            "thinking": level, "api_params": {"max_tokens": max_tokens, **params},
            "seconds": round(time.time() - start, 2), "raw_api_response": raw}


def make_prompt(spec, reqs, seed):
    """Build the Study 1 prompt. Requirements are shuffled with a fixed seed. Return (prompt, requirement IDs in order)."""
    reqs = reqs[:]
    random.Random(seed).shuffle(reqs)
    lines = "\n".join(f"{i}. {r['text']}" for i, r in enumerate(reqs, 1))
    prompt = (f"Implement the following Python module.\n\n## Description\n{spec['description']}\n"
              f"## API (implement exactly these names and signatures)\n```python\n{spec['api']}```\n\n"
              f"## Requirements\n{lines}\n\n"
              "Return the complete implementation of the module as a single Python code block.")
    return prompt, [r["id"] for r in reqs]


def run_tests(code, app_dir, module):
    """Run every requirement test on the code in a fresh folder.

    Returns ({requirement ID: passed}, crashed, error). crashed means the module cannot be imported;
    then every requirement counts as failed.
    """
    with tempfile.TemporaryDirectory() as tmp:
        Path(tmp, f"{module}.py").write_text(code)
        tests = sorted((app_dir / "tests").glob("test_*.py"))
        try:
            imp = subprocess.run([sys.executable, "-c", f"import {module}"], cwd=tmp,
                                 capture_output=True, text=True, timeout=20)
            crashed, error = imp.returncode != 0, "\n".join(imp.stderr.strip().splitlines()[-6:])
        except subprocess.TimeoutExpired:
            crashed, error = True, "import took longer than 20 s (e.g. waiting for input() or an endless loop)"
        if crashed:
            return {t.stem[5:]: False for t in tests}, True, error
        result = {}
        for test in tests:
            shutil.copy(test, tmp)
            try:
                ok = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", test.name],
                                    cwd=tmp, capture_output=True, timeout=30).returncode == 0
            except subprocess.TimeoutExpired:
                ok = False
            result[test.stem[5:]] = ok
        return result, False, ""


def write_atomic(path, text):
    """Write through a temporary file, so a half-written file is never visible."""
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    tmp.write_text(text)
    os.replace(tmp, path)


def save_json(path, record):
    if path.exists():
        raise RuntimeError(f"{path} already exists, not overwriting")
    write_atomic(path, json.dumps({"experiment": RUN["experiment"], "run_id": RUN["run_id"],
                                   "timestamp": now(), **record}, indent=1, default=str))


def write_csv(path, rows):
    buf = io.StringIO()
    csv.writer(buf).writerows(rows)
    write_atomic(path, buf.getvalue())


def print_result(path, passed, crashed, error, truncated):
    print(f"{path.stem}: {sum(passed.values())}/{len(passed)}{' CRASH' if crashed else ''}"
          f"{' TRUNCATED' if truncated else ''} | spent {SPENT['usd']:.3f} USD")
    if crashed:
        print("    " + (error.splitlines()[-1] if error else "empty code"))


def check():
    """Every reference.py must pass all tests; every mutants/<ID>.py must fail exactly test <ID>."""
    for app_dir in sorted(APPS.iterdir()):
        spec = yaml.safe_load((app_dir / "spec.yaml").read_text())
        ref, _, _ = run_tests((app_dir / "reference.py").read_text(), app_dir, spec["module"])
        print(app_dir.name, "reference:", "OK" if all(ref.values()) else f"ERROR {ref}")
        for mutant in sorted((app_dir / "mutants").glob("*.py")):
            res, _, _ = run_tests(mutant.read_text(), app_dir, spec["module"])
            failed = [k for k, ok in res.items() if not ok]
            print(f"  mutant {mutant.stem}: {'OK' if failed == [mutant.stem] else f'fails {failed}'}")


def guard_app_changes(out, apps):
    """Stop if this experiment already has results for a different version of the requirements or tests."""
    known = {}
    for f in out.rglob("*.json"):
        d = json.loads(f.read_text())
        known.setdefault(d["app"], set()).add(d.get("app_hash"))
    for app in apps:
        if app in known and known[app] != {app_hash(APPS / app)}:
            sys.exit(f"Requirements or tests of {app} changed since earlier runs of '{RUN['experiment']}'. "
                     "Use a new --name.")


def guard_settings(out, models):
    """Stop if this experiment already has results of a model with different SETTINGS."""
    for f in out.rglob("*.json"):
        d = json.loads(f.read_text())
        if d.get("model") in models and "api_params" in d:
            _, max_tokens, params = settings(d["model"])
            if d["api_params"] != json.loads(json.dumps({"max_tokens": max_tokens, **params})):
                sys.exit(f"SETTINGS of {d['model']} differ from earlier runs of '{out.name}' "
                         f"({d['api_params']}). Use a new --name.")


def generate(a):
    for model in a.models.split(","):
        for app in a.apps.split(","):
            app_dir = APPS / app
            spec = yaml.safe_load((app_dir / "spec.yaml").read_text())
            reqs = spec["requirements"]
            conditions = [("FULL", reqs)] + [(f"ABL-{r['id']}", [q for q in reqs if q is not r]) for r in reqs]
            for cond, shown in conditions:
                for rep in range(a.reps):
                    path = RUN["out"] / f"{app}__{model}__{cond}__{rep}.json"
                    if path.exists():
                        continue
                    prompt, order = make_prompt(spec, shown, f"{app}{model}{cond}{rep}")
                    try:
                        r = call(model, prompt, app_dir)
                    except CallFailed as e:
                        print(f"[skipped] {path.stem}: {e}")
                        continue
                    passed, crashed, error = run_tests(r["code"], app_dir, spec["module"])
                    save_json(path, {"app": app, "app_hash": app_hash(app_dir), "model": model,
                                     "condition": cond, "rep": rep, "requirement_order": order,
                                     "passed": passed, "crashed": crashed, "error": error, **r})
                    print_result(path, passed, crashed, error, r["truncated"])


def erosion(a):
    variant = "refactor" if a.refactor else "code"
    for model in a.models.split(","):
        for app in a.apps.split(","):
            app_dir = APPS / app
            spec = yaml.safe_load((app_dir / "spec.yaml").read_text())
            changes = [REFACTOR] if a.refactor else spec["changes"]
            for rep in range(a.reps):
                start = RUN["out"] / f"{app}__{model}__FULL__{rep}.json"
                if not start.exists():
                    print(f"Missing {start.name}; run the main experiment with the same --name first.")
                    continue
                code = json.loads(start.read_text())["code"]
                for step, change in enumerate(changes, 1):
                    path = RUN["out"] / "erosion" / f"{app}__{model}__{variant}__{rep}__{step}.json"
                    if path.exists():
                        code = json.loads(path.read_text())["code"]
                        continue
                    prompt = (f"Here is the current implementation of a Python module.\n```python\n{code}```\n\n"
                              f"## Change request\n{change}\n\n"
                              "Keep all existing functions and their signatures. "
                              "Return the complete updated module as a single Python code block.")
                    try:
                        r = call(model, prompt, app_dir)
                    except CallFailed as e:
                        print(f"[skipped, later steps of this chain on the next run] {path.stem}: {e}")
                        break
                    code = r["code"]
                    passed, crashed, error = run_tests(code, app_dir, spec["module"])
                    save_json(path, {"app": app, "app_hash": app_hash(app_dir), "model": model,
                                     "variant": variant, "rep": rep, "step": step, "change": change,
                                     "start_file": start.name, "passed": passed, "crashed": crashed,
                                     "error": error, **r})
                    print_result(path, passed, crashed, error, r["truncated"])


def save_csv(out):
    """Rebuild the CSV files from all JSON files of an experiment.

    results.csv          one row per request and requirement. in_prompt is False for the removed
                         requirement of an ABL run (these rows give P_default); FULL rows give P_stated.
    results_erosion.csv  one row per chain step and requirement; step 0 is the starting FULL code.
    """
    category = {r["id"]: r["category"] for d in APPS.iterdir()
                for r in yaml.safe_load((d / "spec.yaml").read_text())["requirements"]}
    common = ["experiment", "run_id", "timestamp", "app", "app_hash", "model", "model_id"]
    usage = ["crashed", "truncated", "input_tokens", "output_tokens", "cost_usd", "seconds", "json_file"]

    rows = []
    for f in sorted(out.glob("*.json")):
        d = json.loads(f.read_text())
        order = d["requirement_order"]
        for rid, ok in d["passed"].items():
            rows.append([d[k] for k in common] + [d["condition"], d["rep"], rid, category[rid],
                        rid in order, order.index(rid) + 1 if rid in order else "", int(ok)]
                        + [int(d["crashed"]), int(d.get("truncated", False)), d["input_tokens"],
                           d["output_tokens"], d["cost_usd"], d["seconds"], f.name])
    write_csv(out / "results.csv", [common + ["condition", "rep", "req_id", "category", "in_prompt",
                                             "position", "passed"] + usage] + rows)
    print(f"Saved {out.relative_to(ROOT)}/results.csv ({len(rows)} rows)")

    rows = []
    for f in sorted((out / "erosion").glob("*.json")):
        d = json.loads(f.read_text())
        if d["step"] == 1:
            s = json.loads((out / d["start_file"]).read_text())
            rows += [[s[k] for k in common] + [d["variant"], d["rep"], 0, "", rid, category[rid], int(ok)]
                     + [int(s["crashed"]), int(s.get("truncated", False)), "", "", "", "", d["start_file"]]
                     for rid, ok in s["passed"].items()]
        rows += [[d[k] for k in common] + [d["variant"], d["rep"], d["step"], d["change"], rid,
                 category[rid], int(ok)] + [int(d["crashed"]), int(d.get("truncated", False)),
                 d["input_tokens"], d["output_tokens"], d["cost_usd"], d["seconds"], f"erosion/{f.name}"]
                 for rid, ok in d["passed"].items()]
    if rows:
        write_csv(out / "results_erosion.csv", [common + ["variant", "rep", "step", "change", "req_id",
                                                         "category", "passed"] + usage] + rows)
        print(f"Saved {out.relative_to(ROOT)}/results_erosion.csv ({len(rows)} rows)")


def main():
    p = argparse.ArgumentParser(description="Study 1: generate code with LLMs and test every requirement.")
    p.add_argument("--name", default="test", help="experiment name, results go to results/<name>/")
    p.add_argument("--models", default="mock", help="comma-separated keys of MODELS")
    p.add_argument("--apps", default=",".join(d.name for d in sorted(APPS.iterdir())))
    p.add_argument("--reps", type=int, default=3)
    p.add_argument("--budget", type=float, default=1.0, help="spending limit in USD for this run")
    p.add_argument("--check", action="store_true", help="validate the tests with reference and mutants")
    p.add_argument("--erosion", action="store_true", help="apply the change requests to the FULL code")
    p.add_argument("--refactor", action="store_true", help="with --erosion: one refactoring step instead")
    p.add_argument("--report", action="store_true", help="only rebuild the CSV files")
    a = p.parse_args()
    if a.check:
        return check()
    if a.report:
        return save_csv(ROOT / "results" / a.name)
    for model in a.models.split(","):
        settings(model)

    out = ROOT / "results" / a.name
    out.mkdir(parents=True, exist_ok=True)
    RUN.update(experiment=a.name, out=out,
               run_id=datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-") + os.urandom(2).hex())
    guard_app_changes(out, a.apps.split(","))
    guard_settings(out, a.models.split(","))
    SPENT["budget"] = a.budget

    log = {"run_id": RUN["run_id"], "started": now(), "args": vars(a),
           "script_sha": hashlib.sha256(Path(__file__).read_bytes()).hexdigest()[:12],
           "apps": {app: app_hash(APPS / app) for app in a.apps.split(",")},
           "models": {m: MODELS[m][2:] for m in a.models.split(",")},
           "settings": {m: settings(m)[:2] for m in a.models.split(",")}}
    try:
        erosion(a) if a.erosion else generate(a)
        log["status"] = "complete"
    except BudgetExceeded:
        log["status"] = "budget_reached"
        print(f"Budget of {a.budget} USD reached. Run again to continue.")
    log.update(finished=now(), spent_usd=round(SPENT["usd"], 6))
    with open(out / "runs.jsonl", "a") as fh:
        fh.write(json.dumps(log) + "\n")
    print(f"Run {RUN['run_id']}: spent {SPENT['usd']:.3f} USD")
    save_csv(out)
    if log["status"] != "complete":
        sys.exit(2)


if __name__ == "__main__":
    main()
